1	"use client";
2	
3	import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
4	import type { CalendarInfo, CalEvent, TaskItem, EventInput } from "@/lib/calendar/types";
5	import {
6	  listEvents,
7	  createEvent,
8	  updateEvent,
9	  deleteEvent,
10	  listTasks,
11	  createTask,
12	  setTaskCompleted,
13	  deleteTask,
14	} from "@/lib/actions-calendar";
15	import {
16	  Icon,
17	  addDays,
18	  addMonths,
19	  calColor,
20	  endOfDay,
21	  monthGrid,
22	  rangeTitle,
23	  startOfDay,
24	  weekDays,
25	} from "./util";
26	import { MiniCalendar } from "./MiniCalendar";
27	import { MonthView } from "./MonthView";
28	import { WeekView } from "./WeekView";
29	import { TaskPanel } from "./TaskPanel";
30	import { EventModal, type EventDraft } from "./EventModal";
31	
32	type View = "month" | "week" | "day";
33	
34	function computeRange(view: View, cursor: Date): [string, string] {
35	  if (view === "month") {
36	    const grid = monthGrid(cursor);
37	    return [startOfDay(grid[0]).toISOString(), endOfDay(grid[grid.length - 1]).toISOString()];
38	  }
39	  if (view === "week") {
40	    const days = weekDays(cursor);
41	    return [startOfDay(days[0]).toISOString(), endOfDay(days[6]).toISOString()];
42	  }
43	  return [startOfDay(cursor).toISOString(), endOfDay(cursor).toISOString()];
44	}
45	
46	/** A fresh event draft anchored at the given start, lasting one hour. */
47	function newDraft(calendarId: string, start: Date, allDay = false): EventDraft {
48	  const end = new Date(start.getTime() + 60 * 60 * 1000);
49	  return {
50	    calendarId,
51	    title: "",
52	    start: start.toISOString(),
53	    end: end.toISOString(),
54	    allDay,
55	    location: "",
56	    description: "",
57	  };
58	}
59	
60	export function CalendarClient({
61	  initialCalendars,
62	  initialEvents,
63	  initialTasks,
64	}: {
65	  initialCalendars: CalendarInfo[];
66	  initialEvents: CalEvent[];
67	  initialTasks: TaskItem[];
68	}) {
69	  const calendars = initialCalendars;
70	  const writableCals = calendars.filter((c) => !c.readOnly);
71	  const taskCalId = writableCals[0]?.id ?? calendars[0]?.id ?? "";
72	
73	  const [view, setView] = useState<View>("month");
74	  const [cursor, setCursor] = useState<Date>(() => new Date());
75	  const [events, setEvents] = useState<CalEvent[]>(initialEvents);
76	  const [tasks, setTasks] = useState<TaskItem[]>(initialTasks);
77	  const [hidden, setHidden] = useState<Set<string>>(new Set());
78	  const [modal, setModal] = useState<EventDraft | null>(null);
79	  const [toast, setToast] = useState<string | null>(null);
80	  const [railOpen, setRailOpen] = useState(false);
81	  const [tasksLoading, setTasksLoading] = useState(false);
82	
83	  const [pending, startFetch] = useTransition();
84	  const firstRun = useRef(true);
85	
86	  /* ---- Colours ---------------------------------------------------------- */
87	  const colorMap = useMemo(() => {
88	    const m = new Map<string, string>();
89	    calendars.forEach((c, i) => m.set(c.id, calColor(c, i)));
90	    return m;
91	  }, [calendars]);
92	  const colorFor = useCallback((id: string) => colorMap.get(id) ?? calColor(undefined, 0), [colorMap]);
93	
94	  /* ---- Fetch events for the visible range ------------------------------- */
95	  const refetch = useCallback(
96	    (v: View, c: Date) => {
97	      const [s, e] = computeRange(v, c);
98	      startFetch(async () => {
99	        try {
100	          const evs = await listEvents(s, e);
101	          setEvents(evs);
102	        } catch {
103	          setToast("Couldn't load events.");
104	        }
105	      });
106	    },
107	    []
108	  );
109	
110	  // Refetch whenever view or cursor range changes (skip the first render — the
111	  // server already handed us events for the current month).
112	  const rangeKey = computeRange(view, cursor).join("|");
113	  useEffect(() => {
114	    if (firstRun.current) {
115	      firstRun.current = false;
116	      return;
117	    }
118	    refetch(view, cursor);
119	    // eslint-disable-next-line react-hooks/exhaustive-deps
120	  }, [rangeKey]);
121	
122	  /* ---- Visible events + busy-day markers --------------------------------- */
123	  const visibleEvents = useMemo(() => events.filter((e) => !hidden.has(e.calendarId)), [events, hidden]);
124	  const busyDays = useMemo(() => {
125	    const s = new Set<string>();
126	    for (const e of visibleEvents) {
127	      const d = new Date(e.start);
128	      s.add(`${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`);
129	    }
130	    return s;
131	  }, [visibleEvents]);
132	
133	  /* ---- Navigation ------------------------------------------------------- */
134	  const goToday = () => setCursor(new Date());
135	  const step = (dir: 1 | -1) => {
136	    setCursor((c) => (view === "month" ? addMonths(c, dir) : addDays(c, dir * (view === "week" ? 7 : 1))));
137	  };
138	  const pickDay = (d: Date, toDay = false) => {
139	    setCursor(d);
140	    if (toDay) setView("day");
141	    setRailOpen(false);
142	  };
143	
144	  /* ---- Event create / edit ---------------------------------------------- */
145	  const openNew = (start: Date, allDay = false) => {
146	    if (!taskCalId) {
147	      setToast("No writable calendar available.");
148	      return;
149	    }
150	    setModal(newDraft(taskCalId, start, allDay));
151	  };
152	  const openCreateOnDay = (day: Date) => {
153	    // A day cell in month view → 9:00 AM that day by default.
154	    const start = new Date(day.getFullYear(), day.getMonth(), day.getDate(), 9, 0, 0);
155	    openNew(start);
156	  };
157	  const openCreateAt = (day: Date, hour: number) => {
158	    openNew(new Date(day.getFullYear(), day.getMonth(), day.getDate(), hour, 0, 0));
159	  };
160	  const openHeaderNew = () => {
161	    const now = new Date();
162	    const start = new Date(now.getFullYear(), now.getMonth(), now.getDate(), now.getHours() + 1, 0, 0);
163	    openNew(start);
164	  };
165	  const openEvent = (ev: CalEvent) => {
166	    setModal({
167	      id: ev.id,
168	      calendarId: ev.calendarId,
169	      title: ev.title,
170	      start: ev.start,
171	      end: ev.end,
172	      allDay: ev.allDay,
173	      location: ev.location ?? "",
174	      description: ev.description ?? "",
175	    });
176	  };
177	
178	  const saveEvent = async (input: EventInput, id?: string) => {
179	    const res = id ? await updateEvent(id, input) : await createEvent(input);
180	    if (res && res.ok === false) throw new Error(res.error || "The calendar server rejected the event.");
181	    setToast(id ? "Event updated." : "Event created.");
182	    refetch(view, cursor);
183	  };
184	
185	  const removeEvent = async (id: string) => {
186	    setEvents((cur) => cur.filter((e) => e.id !== id)); // optimistic
187	    setToast("Event deleted.");
188	    try {
189	      await deleteEvent(id);
190	    } catch {
191	      setToast("Couldn't delete the event.");
192	    } finally {
193	      refetch(view, cursor);
194	    }
195	  };
196	
197	  /* ---- Tasks (optimistic) ----------------------------------------------- */
198	  const reloadTasks = useCallback(async () => {
199	    setTasksLoading(true);
200	    try {
201	      setTasks(await listTasks());
202	    } catch {
203	      /* keep current */
204	    } finally {
205	      setTasksLoading(false);
206	    }
207	  }, []);
208	
209	  const addTask = (title: string, due?: string) => {
210	    if (!taskCalId) {
211	      setToast("No writable calendar for tasks.");
212	      return;
213	    }
214	    const temp: TaskItem = {
215	      id: `tmp-${Date.now()}`,
216	      uid: `tmp-${Date.now()}`,
217	      calendarId: taskCalId,
218	      title,
219	      due,
220	      completed: false,
221	    };
222	    setTasks((cur) => [temp, ...cur]);
223	    void (async () => {
224	      try {
225	        const res = await createTask({ calendarId: taskCalId, title, due });
226	        if (res && res.ok === false) throw new Error(res.error || "The calendar server rejected the task.");
227	        await reloadTasks();
228	      } catch (err) {
229	        setTasks((cur) => cur.filter((t) => t.id !== temp.id));
230	        setToast(err instanceof Error ? err.message : "Couldn't add the task.");
231	      }
232	    })();
233	  };
234	
235	  const toggleTask = (id: string, completed: boolean) => {
236	    setTasks((cur) => cur.map((t) => (t.id === id ? { ...t, completed } : t)));
237	    void setTaskCompleted(id, completed).catch(() => {
238	      setTasks((cur) => cur.map((t) => (t.id === id ? { ...t, completed: !completed } : t)));
239	      setToast("Couldn't update the task.");
240	    });
241	  };
242	
243	  const removeTask = (id: string) => {
244	    const prev = tasks;
245	    setTasks((cur) => cur.filter((t) => t.id !== id));
246	    void deleteTask(id).catch(() => {
247	      setTasks(prev);
248	      setToast("Couldn't delete the task.");
249	    });
250	  };
251	
252	  /* ---- Toast auto-dismiss ------------------------------------------------ */
253	  useEffect(() => {
254	    if (!toast) return;
255	    const t = setTimeout(() => setToast(null), 2600);
256	    return () => clearTimeout(t);
257	  }, [toast]);
258	
259	  /* ---- Keyboard shortcuts ----------------------------------------------- */
260	  useEffect(() => {
261	    const onKey = (e: KeyboardEvent) => {
262	      if (modal) return;
263	      const el = document.activeElement as HTMLElement | null;
264	      const typing = !!el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA" || el.tagName === "SELECT" || el.isContentEditable);
265	      if (typing || e.metaKey || e.ctrlKey || e.altKey) return;
266	      switch (e.key) {
267	        case "t": e.preventDefault(); goToday(); break;
268	        case "m": e.preventDefault(); setView("month"); break;
269	        case "w": e.preventDefault(); setView("week"); break;
270	        case "d": e.preventDefault(); setView("day"); break;
271	        case "n": e.preventDefault(); openHeaderNew(); break;
272	        case "ArrowLeft": e.preventDefault(); step(-1); break;
273	        case "ArrowRight": e.preventDefault(); step(1); break;
274	        default: break;
275	      }
276	    };
277	    window.addEventListener("keydown", onKey);
278	    return () => window.removeEventListener("keydown", onKey);
279	    // eslint-disable-next-line react-hooks/exhaustive-deps
280	  }, [modal, view]);
281	
282	  /* ---- Left rail contents ----------------------------------------------- */
283	  const rail = (
284	    <div className="flex h-full flex-col gap-4 p-3">
285	      <button onClick={openHeaderNew} className="btn-primary w-full">
286	        <Icon.plus size={16} /> New event
287	      </button>
288	
289	      <MiniCalendar cursor={cursor} selected={cursor} onPick={(d) => pickDay(d)} busyDays={busyDays} />
290	
291	      {/* Calendar list */}
292	      <div>
293	        <p className="section-label mb-2">Calendars</p>
294	        <div className="space-y-0.5">
295	          {calendars.map((c, i) => {
296	            const color = calColor(c, i);
297	            const on = !hidden.has(c.id);
298	            return (
299	              <button
300	                key={c.id}
301	                onClick={() =>
302	                  setHidden((cur) => {
303	                    const n = new Set(cur);
304	                    if (n.has(c.id)) n.delete(c.id);
305	                    else n.add(c.id);
306	                    return n;
307	                  })
308	                }
309	                className="group flex w-full items-center gap-2.5 rounded-lg px-1.5 py-1.5 text-left transition-colors hover:bg-white/[0.03]"
310	              >
311	                <span
312	                  className={`flex h-4 w-4 flex-none items-center justify-center rounded-[5px] border transition-colors ${on ? "border-transparent" : "border-white/20"}`}
313	                  style={on ? { backgroundColor: color } : undefined}
314	                >
315	                  {on && <Icon.check size={11} className="text-white" />}
316	                </span>
317	                <span className={`min-w-0 flex-1 truncate text-[13px] ${on ? "text-slate-200" : "text-slate-500"}`}>
318	                  {c.name}
319	                </span>
320	                {c.readOnly && <span className="flex-none text-[10px] uppercase text-slate-600">RO</span>}
321	              </button>
322	            );
323	          })}
324	        </div>
325	      </div>
326	
327	      <div className="divider !my-0" />
328	
329	      {/* Tasks */}
330	      <div className="min-h-0 flex-1">
331	        <TaskPanel
332	          tasks={tasks}
333	          loading={tasksLoading}
334	          canAdd={!!taskCalId}
335	          onAdd={addTask}
336	          onToggle={toggleTask}
337	          onDelete={removeTask}
338	        />
339	      </div>
340	    </div>
341	  );
342	
343	  /* ---- Render ----------------------------------------------------------- */
344	  return (
345	    <div
346	      className="relative flex h-full min-h-[560px] overflow-hidden border-t border-white/[0.06] bg-navy-900/60 backdrop-blur-md"
347	    >
348	      {/* Left rail — static on lg+, slide-over on smaller */}
349	      <aside className="hidden w-64 flex-none overflow-y-auto border-r border-white/[0.06] bg-navy-950/30 lg:block">
350	        {rail}
351	      </aside>
352	
353	      {railOpen && (
354	        <div className="absolute inset-0 z-40 lg:hidden">
355	          <div className="absolute inset-0 bg-navy-950/70 backdrop-blur-sm" onClick={() => setRailOpen(false)} />
356	          <div className="absolute inset-y-0 left-0 w-72 overflow-y-auto border-r border-white/[0.06] bg-navy-900 shadow-2xl animate-fade-up">
357	            {rail}
358	          </div>
359	        </div>
360	      )}
361	
362	      {/* Main column */}
363	      <section className="flex min-w-0 flex-1 flex-col">
364	        {/* Toolbar */}
365	        <div className="flex flex-none flex-wrap items-center gap-2 border-b border-white/[0.06] px-3 py-2.5 sm:px-4">
366	          <button onClick={() => setRailOpen(true)} className="btn-ghost rounded-lg p-1.5 lg:hidden" aria-label="Open sidebar">
367	            <Icon.menu size={18} />
368	          </button>
369	
370	          <button onClick={goToday} className="btn-secondary px-3 py-1.5 text-sm">
371	            Today
372	          </button>
373	
374	          <div className="flex items-center">
375	            <button onClick={() => step(-1)} className="btn-ghost rounded-lg p-1.5" aria-label="Previous">
376	              <Icon.chevronLeft size={18} />
377	            </button>
378	            <button onClick={() => step(1)} className="btn-ghost rounded-lg p-1.5" aria-label="Next">
379	              <Icon.chevronRight size={18} />
380	            </button>
381	          </div>
382	
383	          <h2 className="min-w-0 flex-1 truncate text-base font-semibold text-slate-100 sm:text-lg">
384	            {rangeTitle(view, cursor)}
385	          </h2>
386	
387	          {/* Refetch spinner */}
388	          {pending && <Icon.refresh size={15} className="flex-none animate-spin text-brand-300" />}
389	
390	          {/* View switcher */}
391	          <div className="flex flex-none items-center rounded-xl border border-white/10 bg-white/[0.03] p-0.5">
392	            {(["month", "week", "day"] as View[]).map((v) => (
393	              <button
394	                key={v}
395	                onClick={() => setView(v)}
396	                className={`rounded-lg px-2.5 py-1 text-xs font-semibold capitalize transition-colors sm:px-3 ${
397	                  view === v ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white shadow" : "text-slate-400 hover:text-white"
398	                }`}
399	              >
400	                {v}
401	              </button>
402	            ))}
403	          </div>
404	
405	          <button onClick={openHeaderNew} className="btn-primary hidden px-3 py-1.5 text-sm sm:inline-flex">
406	            <Icon.plus size={15} /> New
407	          </button>
408	        </div>
409	
410	        {/* View body */}
411	        <div className="min-h-0 flex-1">
412	          {view === "month" ? (
413	            <MonthView
414	              cursor={cursor}
415	              events={visibleEvents}
416	              colorFor={colorFor}
417	              onCreateOn={openCreateOnDay}
418	              onOpenEvent={openEvent}
419	              onPickDay={(d) => pickDay(d, true)}
420	            />
421	          ) : (
422	            <WeekView
423	              days={view === "week" ? weekDays(cursor) : [cursor]}
424	              events={visibleEvents}
425	              colorFor={colorFor}
426	              onCreateAt={openCreateAt}
427	              onOpenEvent={openEvent}
428	              onPickDay={(d) => pickDay(d, true)}
429	            />
430	          )}
431	        </div>
432	      </section>
433	
434	      {/* Floating new-event button (mobile) */}
435	      <button
436	        onClick={openHeaderNew}
437	        aria-label="New event"
438	        className="btn-primary absolute bottom-4 right-4 z-30 h-12 w-12 rounded-full p-0 shadow-2xl sm:hidden"
439	      >
440	        <Icon.plus size={20} />
441	      </button>
442	
443	      {/* Event modal */}
444	      {modal && (
445	        <EventModal
446	          draft={modal}
447	          calendars={calendars}
448	          colorFor={colorFor}
449	          onClose={() => setModal(null)}
450	          onSave={saveEvent}
451	          onDelete={removeEvent}
452	        />
453	      )}
454	
455	      {/* Toast */}
456	      {toast && (
457	        <div className="pointer-events-none absolute bottom-4 left-1/2 z-50 -translate-x-1/2">
458	          <div className="glass flex items-center gap-2 px-4 py-2.5 text-sm text-slate-100 shadow-2xl animate-fade-up">
459	            <span className="text-brand-300"><Icon.calendar size={15} /></span>
460	            {toast}
461	          </div>
462	        </div>
463	      )}
464	    </div>
465	  );
466	}
