1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import type { CalendarInfo, EventInput } from "@/lib/calendar/types";
5	import {
6	  Icon,
7	  isoToDateInput,
8	  isoToLocalInput,
9	  localInputToIso,
10	  endOfDay,
11	  startOfDay,
12	} from "./util";
13	
14	export type EventDraft = {
15	  id?: string; // set when editing an existing event
16	  calendarId: string;
17	  title: string;
18	  start: string; // ISO
19	  end: string; // ISO
20	  allDay: boolean;
21	  location: string;
22	  description: string;
23	};
24	
25	export function EventModal({
26	  draft,
27	  calendars,
28	  colorFor,
29	  onClose,
30	  onSave,
31	  onDelete,
32	}: {
33	  draft: EventDraft;
34	  calendars: CalendarInfo[];
35	  colorFor: (calendarId: string) => string;
36	  onClose: () => void;
37	  onSave: (input: EventInput, id?: string) => Promise<void>;
38	  onDelete: (id: string) => Promise<void>;
39	}) {
40	  const writable = calendars.filter((c) => !c.readOnly);
41	  const [calendarId, setCalendarId] = useState(draft.calendarId || writable[0]?.id || calendars[0]?.id || "");
42	  const [title, setTitle] = useState(draft.title);
43	  const [allDay, setAllDay] = useState(draft.allDay);
44	  const [start, setStart] = useState(draft.start);
45	  const [end, setEnd] = useState(draft.end);
46	  const [location, setLocation] = useState(draft.location);
47	  const [description, setDescription] = useState(draft.description);
48	  const [saving, setSaving] = useState(false);
49	  const [deleting, setDeleting] = useState(false);
50	  const [confirmDel, setConfirmDel] = useState(false);
51	  const [error, setError] = useState<string | null>(null);
52	
53	  const editing = !!draft.id;
54	  const activeCal = calendars.find((c) => c.id === calendarId);
55	  const readOnly = !!activeCal?.readOnly;
56	
57	  useEffect(() => {
58	    const onKey = (e: KeyboardEvent) => {
59	      if (e.key === "Escape" && !saving && !deleting) onClose();
60	      if ((e.metaKey || e.ctrlKey) && e.key === "Enter" && !readOnly) void submit();
61	    };
62	    window.addEventListener("keydown", onKey);
63	    return () => window.removeEventListener("keydown", onKey);
64	    // eslint-disable-next-line react-hooks/exhaustive-deps
65	  }, [title, start, end, allDay, location, description, calendarId, saving, deleting]);
66	
67	  // Keep end >= start when start moves.
68	  const onStartChange = (iso: string) => {
69	    setStart(iso);
70	    if (new Date(iso).getTime() > new Date(end).getTime()) {
71	      setEnd(new Date(new Date(iso).getTime() + 60 * 60 * 1000).toISOString());
72	    }
73	  };
74	
75	  async function submit() {
76	    if (saving || readOnly) return;
77	    if (!title.trim()) {
78	      setError("Give the event a title.");
79	      return;
80	    }
81	    if (new Date(end).getTime() < new Date(start).getTime()) {
82	      setError("End time can't be before the start.");
83	      return;
84	    }
85	    setError(null);
86	    setSaving(true);
87	    try {
88	      const s = allDay ? startOfDay(new Date(start)).toISOString() : start;
89	      const e = allDay ? endOfDay(new Date(end)).toISOString() : end;
90	      await onSave(
91	        {
92	          calendarId,
93	          title: title.trim(),
94	          start: s,
95	          end: e,
96	          allDay,
97	          location: location.trim() || undefined,
98	          description: description.trim() || undefined,
99	        },
100	        draft.id
101	      );
102	      onClose();
103	    } catch (err) {
104	      setError(err instanceof Error ? err.message : "Couldn't save the event.");
105	      setSaving(false);
106	    }
107	  }
108	
109	  async function remove() {
110	    if (!draft.id || deleting) return;
111	    setDeleting(true);
112	    try {
113	      await onDelete(draft.id);
114	      onClose();
115	    } catch (err) {
116	      setError(err instanceof Error ? err.message : "Couldn't delete the event.");
117	      setDeleting(false);
118	    }
119	  }
120	
121	  return (
122	    <div
123	      className="fixed inset-0 z-50 flex items-end justify-center bg-navy-950/70 p-0 backdrop-blur-sm sm:items-center sm:p-4"
124	      role="dialog"
125	      aria-modal="true"
126	      aria-label={editing ? "Edit event" : "New event"}
127	      onClick={onClose}
128	    >
129	      <div
130	        className="glass flex max-h-[92vh] w-full max-w-lg flex-col overflow-hidden shadow-2xl animate-fade-up"
131	        onClick={(e) => e.stopPropagation()}
132	      >
133	        {/* Header */}
134	        <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
