15	/** Compact month picker in the left rail. Clicking a day jumps the main view;
16	 *  its own month can be paged independently of the main cursor. */
17	export function MiniCalendar({
18	  cursor,
19	  selected,
20	  onPick,
21	  busyDays,
22	}: {
23	  cursor: Date;
24	  selected: Date;
25	  onPick: (d: Date) => void;
26	  busyDays?: Set<string>; // "yyyy-m-d" keys that have events
27	}) {
28	  const [view, setView] = useState(() => new Date(cursor.getFullYear(), cursor.getMonth(), 1));
29	  const days = monthGrid(view);
30	
31	  return (
32	    <div>
33	      <div className="mb-2 flex items-center justify-between">
34	        <span className="text-sm font-semibold text-slate-100">
35	          {MONTHS[view.getMonth()]} {view.getFullYear()}
36	        </span>
37	        <div className="flex items-center gap-0.5">
38	          <button
39	            onClick={() => setView((v) => addMonths(v, -1))}
40	            className="btn-ghost rounded-lg p-1"
41	            aria-label="Previous month"
42	          >
43	            <Icon.chevronLeft size={15} />
44	          </button>
45	          <button
46	            onClick={() => setView((v) => addMonths(v, 1))}
47	            className="btn-ghost rounded-lg p-1"
48	            aria-label="Next month"
49	          >
50	            <Icon.chevronRight size={15} />
51	          </button>
