54	
55	      <div className="grid grid-cols-7 gap-0.5 text-center">
56	        {WEEKDAYS_NARROW.map((d, i) => (
57	          <span key={i} className="py-1 text-[10px] font-semibold text-slate-600">
58	            {d}
59	          </span>
60	        ))}
61	        {days.map((d) => {
62	          const inMonth = isSameMonth(d, view);
63	          const sel = isSameDay(d, selected);
64	          const today = isToday(d);
65	          const busy = busyDays?.has(`${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`);
66	          return (
67	            <button
68	              key={d.toISOString()}
69	              onClick={() => onPick(d)}
70	              className={`relative flex h-7 items-center justify-center rounded-lg text-[12px] transition-colors ${
71	                sel
72	                  ? "bg-gradient-to-r from-accent-blue to-brand-500 font-semibold text-white"
73	                  : today
74	                    ? "font-semibold text-brand-300 hover:bg-white/[0.06]"
75	                    : inMonth
76	                      ? "text-slate-300 hover:bg-white/[0.06]"
77	                      : "text-slate-600 hover:bg-white/[0.04]"
78	              }`}
79	            >
80	              {d.getDate()}
81	              {busy && !sel && (
82	                <span className="absolute bottom-0.5 h-1 w-1 rounded-full bg-brand-400" />
83	              )}
84	            </button>
85	          );
86	        })}
87	      </div>
88	    </div>
89	  );
90	}
