13	
14	/** Month grid; events render as coloured chips inside each day cell. */
15	export function MonthView({
16	  cursor,
17	  events,
18	  colorFor,
19	  onCreateOn,
20	  onOpenEvent,
21	  onPickDay,
22	}: {
23	  cursor: Date;
24	  events: CalEvent[];
25	  colorFor: (calendarId: string) => string;
26	  onCreateOn: (day: Date) => void;
27	  onOpenEvent: (ev: CalEvent) => void;
28	  onPickDay: (day: Date) => void;
29	}) {
30	  const days = monthGrid(cursor);
31	  const MAX_CHIPS = 3;
32	
33	  return (
34	    <div className="flex h-full flex-col">
35	      {/* Weekday header */}
36	      <div className="grid flex-none grid-cols-7 border-b border-white/[0.06]">
37	        {WEEKDAYS_SHORT.map((d) => (
38	          <div key={d} className="px-2 py-2 text-center text-[11px] font-semibold uppercase tracking-wider text-slate-500">
39	            <span className="hidden sm:inline">{d}</span>
40	            <span className="sm:hidden">{d[0]}</span>
41	          </div>
42	        ))}
43	      </div>
44	
45	      {/* 6 week rows */}
46	      <div className="grid flex-1 grid-cols-7 grid-rows-6">
47	        {days.map((day, i) => {
48	          const dayEvents = events
49	            .filter((e) => eventOnDay(e.start, e.end, day))
50	            .sort((a, b) => Number(b.allDay) - Number(a.allDay) || a.start.localeCompare(b.start));
51	          const inMonth = isSameMonth(day, cursor);
52	          const today = isToday(day);
53	          const overflow = dayEvents.length - MAX_CHIPS;
54	
55	          return (
56	            <div
57	              key={day.toISOString()}
58	              onClick={() => onCreateOn(day)}
59	              className={`group relative flex min-h-0 flex-col border-b border-r border-white/[0.05] p-1 text-left transition-colors last:border-r-0 hover:bg-white/[0.02] ${
60	                i % 7 === 6 ? "border-r-0" : ""
61	              } ${inMonth ? "" : "bg-navy-950/30"}`}
62	            >
63	              {/* Day number */}
64	              <div className="mb-0.5 flex flex-none items-center justify-between px-0.5">
65	                <button
66	                  onClick={(e) => {
67	                    e.stopPropagation();
68	                    onPickDay(day);
69	                  }}
70	                  className={`flex h-6 min-w-6 items-center justify-center rounded-full px-1 text-xs font-semibold transition-colors ${
71	                    today
72	                      ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white"
73	                      : inMonth
74	                        ? "text-slate-300 hover:bg-white/[0.08]"
75	                        : "text-slate-600 hover:bg-white/[0.06]"
76	                  }`}
77	                >
78	                  {day.getDate()}
79	                </button>
80	                <button
81	                  onClick={(e) => {
82	                    e.stopPropagation();
83	                    onCreateOn(day);
84	                  }}
85	                  aria-label="Add event"
86	                  className="flex h-5 w-5 items-center justify-center rounded-md text-slate-500 opacity-0 transition-opacity hover:bg-white/[0.08] hover:text-white group-hover:opacity-100"
87	                >
88	                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M12 5v14M5 12h14" /></svg>
89	                </button>
90	              </div>
91	
92	              {/* Event chips */}
93	              <div className="flex min-h-0 flex-1 flex-col gap-0.5 overflow-hidden">
94	                {dayEvents.slice(0, MAX_CHIPS).map((ev) => {
95	                  const color = colorFor(ev.calendarId);
96	                  return (
97	                    <button
98	                      key={ev.id}
99	                      onClick={(e) => {
100	                        e.stopPropagation();
101	                        onOpenEvent(ev);
102	                      }}
103	                      title={ev.title}
104	                      className="flex items-center gap-1.5 truncate rounded-md px-1.5 py-0.5 text-left text-[11px] font-medium leading-tight text-slate-100 transition-colors hover:brightness-125"
105	                      style={{ backgroundColor: hexToRgba(color, ev.allDay ? 0.9 : 0.16) }}
106	                    >
107	                      {!ev.allDay && (
108	                        <span className="h-1.5 w-1.5 flex-none rounded-full" style={{ backgroundColor: color }} />
109	                      )}
110	                      {!ev.allDay && (
111	                        <span className="flex-none text-[10px] tabular-nums text-slate-400">
112	                          {fmtTime(new Date(ev.start))}
113	                        </span>
114	                      )}
115	                      <span className={`truncate ${ev.allDay ? "text-white" : ""}`}>{ev.title || "(untitled)"}</span>
116	                    </button>
117	                  );
118	                })}
119	                {overflow > 0 && (
120	                  <button
121	                    onClick={(e) => {
