16	type Positioned = { ev: CalEvent; top: number; height: number; lane: number; lanes: number };
17	
18	/** Pack overlapping timed events into side-by-side lanes for one day column. */
19	function layoutDay(events: CalEvent[], day: Date): Positioned[] {
20	  const timed = events
21	    .filter((e) => !e.allDay && eventOnDay(e.start, e.end, day))
22	    .sort((a, b) => a.start.localeCompare(b.start));
23	
24	  const out: Positioned[] = [];
25	  // Greedy grouping of mutually-overlapping events into clusters.
26	  let cluster: Positioned[] = [];
27	  let clusterEnd = 0;
28	
29	  const flush = () => {
30	    const lanes = Math.max(1, ...cluster.map((c) => c.lane + 1));
31	    cluster.forEach((c) => (c.lanes = lanes));
32	    out.push(...cluster);
33	    cluster = [];
34	    clusterEnd = 0;
35	  };
36	
37	  for (const ev of timed) {
38	    const top = minutesInto(new Date(ev.start), day);
39	    const bottom = minutesInto(new Date(ev.end), day);
40	    const height = Math.max(18, ((bottom - top) / 60) * HOUR_PX);
41	    const startPx = (top / 60) * HOUR_PX;
42	
43	    if (cluster.length && top >= clusterEnd) flush();
44	
45	    // Find the first free lane within the current cluster.
46	    const taken = new Set(cluster.filter((c) => minutesInto(new Date(c.ev.end), day) > top).map((c) => c.lane));
47	    let lane = 0;
48	    while (taken.has(lane)) lane++;
49	
50	    cluster.push({ ev, top: startPx, height, lane, lanes: 1 });
51	    clusterEnd = Math.max(clusterEnd, bottom);
52	  }
53	  if (cluster.length) flush();
54	  return out;
55	}
