133	/* -------------------------------------------------------------------------- */
134	/* Calendar colours                                                            */
135	/* -------------------------------------------------------------------------- */
136	
137	/** On-brand fallback palette for calendars without an explicit colour. */
138	export const CAL_PALETTE = [
139	  "#6f47f5", // brand-500
140	  "#3b82f6", // accent-blue
141	  "#22d3ee", // accent-cyan
142	  "#a855f7", // violet
143	  "#ec4899", // pink
144	  "#10b981", // emerald
145	  "#f59e0b", // amber
146	  "#f43f5e", // rose
147	];
148	
149	export function calColor(cal: CalendarInfo | undefined, index = 0): string {
150	  const c = cal?.color?.trim();
151	  if (c && /^#?[0-9a-fA-F]{3,8}$/.test(c)) return c.startsWith("#") ? c : `#${c}`;
152	  return CAL_PALETTE[index % CAL_PALETTE.length];
153	}
154	
155	/** hex (#rgb / #rrggbb) -> rgba() string. */
156	export function hexToRgba(hex: string, alpha: number): string {
157	  let h = hex.replace("#", "");
158	  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
159	  const int = parseInt(h.slice(0, 6), 16);
160	  if (Number.isNaN(int)) return `rgba(111,71,245,${alpha})`;
161	  const r = (int >> 16) & 255;
162	  const g = (int >> 8) & 255;
163	  const b = int & 255;
164	  return `rgba(${r},${g},${b},${alpha})`;
165	}
