167	/* -------------------------------------------------------------------------- */
168	/* Event layout helpers (week / day time grid)                                 */
169	/* -------------------------------------------------------------------------- */
170	
171	export const HOUR_PX = 52; // pixel height of one hour row in the time grid
172	
173	/** Minute offset from midnight, clamped to the given day. */
174	export function minutesInto(d: Date, day: Date): number {
175	  const start = startOfDay(day).getTime();
176	  const mins = (d.getTime() - start) / 60_000;
177	  return Math.max(0, Math.min(24 * 60, mins));
178	}
179	
180	/** Does an event (with ISO start/end) intersect the given local day? */
181	export function eventOnDay(startISO: string, endISO: string, day: Date): boolean {
182	  const s = new Date(startISO).getTime();
183	  const e = new Date(endISO).getTime();
184	  const ds = startOfDay(day).getTime();
185	  const de = ds + MS_DAY;
186	  return s < de && e > ds;
187	}
