8	/**
9	 * One-click apps panel.
10	 *
11	 * This UI used to promise "the application in one step" for every card and show
12	 * an "Admin password — save these now" for apps whose install never happened
13	 * (QA P1-22). It now renders the mode the installer actually implements, which
14	 * comes from the server (`APP_MODES` in worker/apps.ts) instead of being restated
15	 * here — so marketing copy and installer behaviour cannot drift apart:
16	 *
17	 *   managed     → installed end to end; admin credentials are real and tested.
18	 *   assisted    → site + database + the app's files are prepared, and the card
19	 *                 says so BEFORE the customer commits; the row settles to
20	 *                 "Finish setup", never to a green install.
21	 *   unavailable → not shown at all.
22	 */
23	export function AppsPanel({ serverId, running }: { serverId: string; running: boolean }) {
24	  const [apps, setApps] = useState<AppRow[] | null>(null);
25	  const [modes, setModes] = useState<AppModeRow[]>([]);
26	  const [error, setError] = useState<string | null>(null);
27	  const [selected, setSelected] = useState<string | null>(null);
28	  const [domain, setDomain] = useState("");
29	  const [adminUser, setAdminUser] = useState("admin");
30	  const [formError, setFormError] = useState<string | null>(null);
31	  const [secret, setSecret] = useState<{ rows: { label: string; value: string }[]; name: string; note: string } | null>(
32	    null
33	  );
34	  const [pending, start] = useTransition();
35	
36	  const refresh = useCallback(async () => {
37	    const res = await listApps(serverId);
38	    if (res.ok) {
39	      setApps(res.apps);
40	      setModes(res.modes);
41	    } else setError(res.error);
42	  }, [serverId]);
43	
44	  useEffect(() => {
45	    void refresh();
46	  }, [refresh]);
47	
48	  useEffect(() => {
49	    if (!apps?.some((a) => ["PENDING", "INSTALLING"].includes(a.status))) return;
50	    const t = setInterval(() => void refresh(), 5000);
51	    return () => clearInterval(t);
52	  }, [apps, refresh]);
53	
54	  const modeOf = useCallback((slug: string) => modes.find((m) => m.slug === slug), [modes]);
55	
56	  /**
57	   * Only the apps this platform can actually deliver. Until `modes` has loaded
58	   * the grid stays empty rather than offering an app we might have withdrawn —
59	   * a card that cannot be honoured must never be clickable.
60	   */
61	  const offered = useMemo(
62	    () => APP_CATALOG.filter((a) => modeOf(a.slug) && modeOf(a.slug)!.mode !== "unavailable"),
