46	// Internal helpers (not exported — this is a "use server" module)
47	// ---------------------------------------------------------------------------
48	
49	/** Reject with a friendly, throttled error when a per-user limit is exceeded. */
50	function enforceRateLimit(key: string, opts: RateLimitOptions) {
51	  const r = checkRateLimit(key, opts);
52	  if (!r.ok) {
53	    throw new Error(`Too many requests — please wait ${r.retryAfterSec}s and try again.`);
54	  }
55	}
56	
57	/** Apply the standard mutation rate limits (short burst + hourly ceiling). */
58	function limitMutations(userId: string) {
59	  enforceRateLimit(`cal:mutate:burst:${userId}`, { max: 30, windowMs: 60 * 1000 });
60	  enforceRateLimit(`cal:mutate:${userId}`, { max: 600, windowMs: 60 * 60 * 1000 });
61	}
62	
63	/** True for a parseable ISO date-time string. */
64	function isValidISO(s: unknown): s is string {
65	  return typeof s === "string" && s.trim() !== "" && !Number.isNaN(Date.parse(s));
66	}
67	
68	/** Short, client-safe message from a thrown value. */
69	function cleanMsg(e: unknown): string {
70	  return String((e as Error)?.message ?? e ?? "Unknown error").slice(0, 300);
71	}
72	
73	/** Normalise a collection/object url for comparison (drop trailing slashes). */
74	function normUrl(u: string): string {
75	  return u.replace(/\/+$/, "");
76	}
77	
78	/** Does a calendar advertise support for the given component (VEVENT/VTODO)? */
79	function supportsComponent(cal: DAVCalendar, comp: string): boolean {
80	  const comps = cal.components;
81	  if (!comps || comps.length === 0) return true; // unknown — include it
82	  return comps.some((c) => c.toUpperCase() === comp);
83	}
84	
85	/** Human-friendly calendar name, falling back to the last url segment. */
86	function calName(cal: DAVCalendar): string {
87	  const dn = cal.displayName;
88	  if (typeof dn === "string" && dn.trim()) return dn.trim();
89	  const leaf = decodeURIComponent(normUrl(cal.url).split("/").pop() || "");
90	  return leaf || "Calendar";
91	}
92	
93	/** Map a tsdav DAVCalendar to the contract CalendarInfo. */
94	function toCalendarInfo(cal: DAVCalendar): CalendarInfo {
95	  return {
96	    id: cal.url,
97	    name: calName(cal),
98	    color: typeof cal.calendarColor === "string" ? cal.calendarColor : undefined,
99	    // SOGo does not surface a reliable per-collection read-only flag over the
100	    // default PROPFIND set; treat collections as writable and let the server
101	    // reject any unauthorised write.
102	    readOnly: false,
103	  };
104	}
105	
106	/** Verify a calendar id belongs to the authenticated account (defense in depth). */
107	async function assertOwnedCalendar(client: DAVClient, calendarId: string): Promise<DAVCalendar> {
108	  const cals = await fetchCalendars(client);
109	  const target = normUrl(calendarId);
110	  const match = cals.find((c) => normUrl(c.url) === target);
111	  if (!match) throw new Error("That calendar was not found in your account.");
112	  return match;
113	}
114	
115	/** The calendar collection url that contains an object href. */
116	function calendarUrlOf(objectHref: string): string {
117	  const i = objectHref.lastIndexOf("/");
118	  return i >= 0 ? objectHref.slice(0, i + 1) : objectHref;
119	}
120	
121	/** Read an existing object's body by its href (or null if it is gone). */
122	async function readObject(client: DAVClient, objectHref: string): Promise<string | null> {
123	  const calUrl = calendarUrlOf(objectHref);
124	  const obj = await fetchObjectByUrl(client, { url: calUrl } as DAVCalendar, objectHref);
125	  return obj?.data ?? null;
126	}
127	
128	/** Validate an EventInput; returns an error message or null when valid. */
129	function validateEventInput(input: EventInput): string | null {
130	  if (!input || typeof input !== "object") return "Invalid event.";
131	  if (!input.calendarId?.trim()) return "Choose a calendar.";
132	  if (!input.title?.trim()) return "Add a title.";
133	  if (!isValidISO(input.start)) return "Invalid start time.";
134	  if (!isValidISO(input.end)) return "Invalid end time.";
135	  if (Date.parse(input.end) < Date.parse(input.start)) return "End must be after start.";
136	  return null;
137	}
138	
139	/** Validate a TaskInput; returns an error message or null when valid. */
140	function validateTaskInput(input: TaskInput): string | null {
141	  if (!input || typeof input !== "object") return "Invalid task.";
142	  if (!input.calendarId?.trim()) return "Choose a calendar.";
143	  if (!input.title?.trim()) return "Add a title.";
144	  if (input.due != null && !isValidISO(input.due)) return "Invalid due date.";
145	  if (
146	    input.priority != null &&
147	    (typeof input.priority !== "number" || input.priority < 0 || input.priority > 9)
148	  ) {
149	    return "Priority must be between 0 and 9.";
150	  }
151	  return null;
152	}
