154	// ---------------------------------------------------------------------------
155	// Calendars
156	// ---------------------------------------------------------------------------
157	
158	/** List the CalDAV calendar collections in the user's account. */
159	export async function listCalendars(mailboxAddress?: string): Promise<CalendarInfo[]> {
160	  const { cred } = await resolveMailbox(mailboxAddress);
161	  const client = await caldavClient(cred);
162	  const cals = await fetchCalendars(client);
163	  return cals.map(toCalendarInfo);
164	}
165	
166	// ---------------------------------------------------------------------------
167	// Events
168	// ---------------------------------------------------------------------------
169	
170	/** All events across the user's calendars overlapping [rangeStart, rangeEnd). */
171	export async function listEvents(
172	  rangeStartISO: string,
173	  rangeEndISO: string,
174	  mailboxAddress?: string,
175	): Promise<CalEvent[]> {
176	  if (!isValidISO(rangeStartISO) || !isValidISO(rangeEndISO)) {
177	    throw new Error("Invalid date range.");
178	  }
179	  const { cred } = await resolveMailbox(mailboxAddress);
180	  const client = await caldavClient(cred);
181	  const cals = (await fetchCalendars(client)).filter((c) => supportsComponent(c, "VEVENT"));
182	
183	  const perCal = await Promise.all(
184	    cals.map(async (cal) => {
185	      const objs = await fetchEventObjects(client, cal, rangeStartISO, rangeEndISO);
186	      return objs.flatMap((o) => (o.data ? parseCalEvents(o.data, cal.url, o.url) : []));
187	    }),
188	  );
189	  return perCal.flat();
190	}
191	
192	/** Create a new event: PUT a fresh .ics object into the target calendar. */
193	export async function createEvent(
194	  input: EventInput,
195	  mailboxAddress?: string,
196	): Promise<{ ok: boolean; id?: string; error?: string }> {
197	  const { user, cred } = await resolveMailbox(mailboxAddress);
198	  limitMutations(user.id);
199	  const invalid = validateEventInput(input);
200	  if (invalid) return { ok: false, error: invalid };
201	
202	  try {
203	    const client = await caldavClient(cred);
204	    const calendar = await assertOwnedCalendar(client, input.calendarId);
205	    const uid = newUID();
206	    const ics = buildEventICS(input, uid);
207	    const id = await putObject(client, calendar.url, `${uid}.ics`, ics);
208	    return { ok: true, id };
209	  } catch (e) {
210	    return { ok: false, error: cleanMsg(e) };
211	  }
212	}
213	
214	/** Update an event in place, preserving its existing UID. */
215	export async function updateEvent(
216	  id: string,
217	  input: EventInput,
218	  mailboxAddress?: string,
219	): Promise<{ ok: boolean; error?: string }> {
220	  const { user, cred } = await resolveMailbox(mailboxAddress);
221	  limitMutations(user.id);
222	  if (!id?.trim()) return { ok: false, error: "Missing event id." };
223	  const invalid = validateEventInput(input);
224	  if (invalid) return { ok: false, error: invalid };
225	
226	  try {
227	    const client = await caldavClient(cred);
228	    const existing = await readObject(client, id);
229	    const uid = (existing && uidFromICS(existing)) || newUID();
230	    const ics = buildEventICS(input, uid);
231	    await putObjectAt(client, id, ics);
232	    return { ok: true };
233	  } catch (e) {
234	    return { ok: false, error: cleanMsg(e) };
235	  }
236	}
237	
238	/** Delete an event by its href. */
239	export async function deleteEvent(id: string, mailboxAddress?: string): Promise<void> {
240	  const { user, cred } = await resolveMailbox(mailboxAddress);
241	  limitMutations(user.id);
242	  if (!id?.trim()) throw new Error("Missing event id.");
243	  const client = await caldavClient(cred);
244	  await deleteObjectAt(client, id);
245	}
