288	/** Mark a task complete/incomplete, preserving its other fields. */
289	export async function setTaskCompleted(
290	  id: string,
291	  completed: boolean,
292	  mailboxAddress?: string,
293	): Promise<void> {
294	  const { user, cred } = await resolveMailbox(mailboxAddress);
295	  limitMutations(user.id);
296	  if (!id?.trim()) throw new Error("Missing task id.");
297	
