151	/**
152	 * Point a website's hostname at the server it lives on, by upserting an A record
153	 * in the customer's Cloudflare zone.
154	 *
155	 * Guards: requireUser + website ownership (via ownedWebsite), rate-limited like
156	 * its neighbours, and the hostname is taken from OUR Website row — never from
157	 * client input — then re-validated inside pointHostnameToIp.
158	 *
159	 * The record is written PROXIED = FALSE (DNS-only). That is deliberate: the name
160	 * must resolve to this server so Let's Encrypt's HTTP-01 challenge reaches
161	 * certbot on the box. Behind Cloudflare's proxy the challenge is answered at
162	 * their edge and SSL issuance fails.
163	 */
164	export async function pointWebsiteDns(id: string): Promise<PointResult> {
165	  try {
166	    const { user, site } = await ownedWebsite(id);
167	    const limited = throttle(user.id, "dns", 12);
168	    if (limited) return { ok: false, error: limited };
169	
170	    const ip = await publicIpOf(site.serverId);
171	    if (!ip) {
172	      return {
173	        ok: false,
174	        error: "This server doesn't have a public IP yet — try again once it has finished provisioning.",
175	      };
176	    }
177	
178	    const res = await pointHostnameToIp({
179	      user: { id: user.id, cloudflareTokenEnc: user.cloudflareTokenEnc },
180	      hostname: site.domain,
181	      ip,
182	    });
183	    if (!res.ok) return { ok: false, error: res.error };
184	
185	    await db.auditLog.create({
186	      data: {
187	        userId: user.id,
188	        action: "cpanel.website.dns",
189	        detail: `${site.domain} A → ${ip}${res.simulated ? " (sandbox)" : ""}`,
190	      },
191	    });
192	    revalidatePath(`/dashboard/servers/${site.serverId}`);
193	
194	    return {
195	      ok: true,
196	      message: res.simulated
197	        ? `Sandbox: pretended to point ${res.hostname} at ${ip} (DNS-only). No record was sent to Cloudflare.`
198	        : `${res.hostname} now points at ${ip} (A record ${res.action}, DNS-only). DNS changes can take a few minutes to reach everyone.`,
199	    };
200	  } catch (err) {
201	    return { ok: false, error: safeError(err) };
202	  }
203	}
