234	    const count = await db.website.count({ where: { serverId: server.id } });
235	    if (count >= 50) return { ok: false, error: "Website limit reached (50 per server)." };
236	
237	    const docRoot = `/var/www/${domain}`;
238	    const site = await db.website.create({
239	      data: {
240	        userId: user.id,
241	        serverId: server.id,
242	        domain,
243	        docRoot,
244	        phpVersion: php,
245	        isSubdomain,
246	        parentDomain: parent,
247	        status: "PENDING",
248	      },
249	    });
