47	async function ownedServer(serverId: string) {
48	  const user = await requireUser();
49	  const server = await db.server.findUnique({
50	    where: { id: serverId },
51	    select: {
52	      id: true,
53	      userId: true,
54	      status: true,
55	      hostname: true,
56	      rootPassword: true,
57	      rootPasswordEnc: true,
58	      sshPort: true,
59	      dedicatedIp: { select: { address: true } },
60	    },
61	  });
62	  if (!server) throw new Error("Not found");
63	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
64	  return { user, server };
65	}
