75	function throttle(userId: string, op: string, max: number): string | null {
76	  const rl = checkRateLimit(`cpanel:cron:${op}:${userId}`, { max, windowMs: 60_000 });
77	  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
78	}
