@import "tailwindcss";

@theme {
  --color-brand-50: #f2f0ff;
  --color-brand-100: #e4e0ff;
  --color-brand-200: #c9c2ff;
  --color-brand-300: #a89aff;
  --color-brand-400: #8a70fb;
  --color-brand-500: #6f47f5;
  --color-brand-600: #5f2ee8;
  --color-brand-700: #5124c4;
  --color-brand-800: #421fa0;
  --color-brand-900: #371d7f;

  --color-navy-950: #060a14;
  --color-navy-900: #0a101f;
  --color-navy-850: #0d1526;
  --color-navy-800: #111a30;
  --color-navy-700: #1a2540;
  --color-navy-600: #253354;

  --color-accent-blue: #3b82f6;
  --color-accent-cyan: #22d3ee;

  --animate-fade-up: fade-up 0.4s ease-out both;
  --animate-pulse-dot: pulse-dot 2s ease-in-out infinite;

  /* Showcase mock-screen animations (marketing product pages). All are opt-in
     via Tailwind's `motion-safe:` variant, so reduced-motion users see the final
     resting state (bars full, lines visible) with no motion. */
  --animate-grow-up: grow-up 0.9s cubic-bezier(0.22, 1, 0.36, 1) both;
  --animate-grow-x: grow-x 1.1s cubic-bezier(0.22, 1, 0.36, 1) both;
  --animate-eq: eq 1.7s ease-in-out infinite;
  --animate-blink: blink 1.1s steps(1) infinite;
  --animate-sweep: sweep 3.4s ease-in-out infinite;
  --animate-line-in: line-in 0.55s cubic-bezier(0.22, 1, 0.36, 1) both;

  @keyframes fade-up {
    from { opacity: 0; transform: translateY(8px); }
    to { opacity: 1; transform: translateY(0); }
  }
  @keyframes pulse-dot {
    0%, 100% { box-shadow: 0 0 0 0 rgb(52 211 153 / 0.5); }
    50% { box-shadow: 0 0 0 5px rgb(52 211 153 / 0); }
  }
  /* One-shot bar grow (origin at the base). Resting state = full. */
  @keyframes grow-up {
    from { transform: scaleY(0.06); }
    to { transform: scaleY(1); }
  }
  /* One-shot progress/usage fill. Resting state = full width. */
  @keyframes grow-x {
    from { transform: scaleX(0); }
    to { transform: scaleX(1); }
  }
  /* Continuous "live traffic" equaliser pulse. Resting state = full height. */
  @keyframes eq {
    0%, 100% { transform: scaleY(0.35); }
    50% { transform: scaleY(1); }
  }
  /* Terminal cursor blink. Resting state = visible. */
  @keyframes blink {
    0%, 49% { opacity: 1; }
    50%, 100% { opacity: 0; }
  }
  /* Soft light sweep across a chart/highlight. */
  @keyframes sweep {
    0% { transform: translateX(-120%); opacity: 0; }
    40%, 60% { opacity: 0.7; }
    100% { transform: translateX(320%); opacity: 0; }
  }
  /* Staggered line/row reveal. Resting state = visible. */
  @keyframes line-in {
    from { opacity: 0; transform: translateY(6px); }
    to { opacity: 1; transform: translateY(0); }
  }
}

