import Link from "next/link";
import { requireUser } from "@/lib/auth";
import { EmptyState } from "@/components/ui/primitives";
import type { CalendarInfo, CalEvent, TaskItem } from "@/lib/calendar/types";
import { listCalendars, listEvents, listTasks } from "@/lib/actions-calendar";
import { CalendarClient } from "@/components/customer/calendar/CalendarClient";

export const dynamic = "force-dynamic";

export const metadata = { title: "Calendar — Nxeon" };

/** Local-time first/last day of the current month grid (6 weeks), so the
 *  initial fetch matches the Month view the client opens on. */
function initialRange(): [string, string] {
  const now = new Date();
  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  const gridStart = new Date(firstOfMonth);
  gridStart.setDate(gridStart.getDate() - gridStart.getDay());
  const gridEnd = new Date(gridStart);
  gridEnd.setDate(gridEnd.getDate() + 42);
  return [gridStart.toISOString(), gridEnd.toISOString()];
}

export default async function CalendarPage() {
  await requireUser();

  let calendars: CalendarInfo[] = [];
  let events: CalEvent[] = [];
  let tasks: TaskItem[] = [];
  let failed = false;

  try {
    calendars = await listCalendars();
    if (calendars.length > 0) {
      const [start, end] = initialRange();
      [events, tasks] = await Promise.all([listEvents(start, end), listTasks()]);
    }
  } catch {
    failed = true;
  }

  if (failed || calendars.length === 0) {
    return (
      <div className="mx-auto max-w-2xl pt-10">
        <EmptyState
          title="No calendar connected"
          sub="Your calendar lives alongside your Nxeon mailbox. Set up business email on one of your domains to start scheduling events and tracking tasks here."
          action={
            <Link href="/dashboard/email" className="btn-primary">
              Set up email
            </Link>
          }
        />
      </div>
    );
  }

  return (
    <CalendarClient initialCalendars={calendars} initialEvents={events} initialTasks={tasks} />
  );

